EVAL=ROOT/'data/predictions/player_model_v2/evaluation'; S30_DIR=ROOT/'data/predictions/player_model_v2/s30'
def j(p,x): p.write_text(json.dumps(x,indent=2,sort_keys=True,default=str)+'\n')
def run(evidence:Path):
 evidence.mkdir(parents=True,exist_ok=False); prior=pd.read_csv(S30_DIR/'2026-player-predictions.csv'); x=s30_predictions(); names,_=build_oe_name_mapping(); x['date']=pd.to_datetime(x.target_cutoff,utc=True).dt.date.astype(str); x['player_name']=x.player_id.map(names); x['share_history_count']=x.groupby('player_id').cumcount(); x['fallback_type']=x.apply(lambda r:'TEAM_T3_SHARE_FALLBACK' if r.prior_fallback else ('ROLE_BASELINE' if pd.isna(r.recent_role_adjusted_component) and pd.isna(r.career_role_adjusted_component) else 'HISTORICAL_SHARE_PRIOR'),axis=1); out=x[['prediction_period_id','target_cutoff','date','player_id','player_name','team_id','role','T3_prediction','T3_team_total','T3_implied_share','historical_share_prior','S30_corrected_share','S30_prediction','share_history_count','fallback_type']].copy(); out['model_id']=S30_ID
 prior_key=prior[['player_id','prediction_period_id','S30_prediction','S30_corrected_share']]; check=out.merge(prior_key,on=['player_id','prediction_period_id'],suffixes=('_runtime','_stage9dc'),validate='one_to_one'); check['prediction_abs_diff']=(check.S30_prediction_runtime-check.S30_prediction_stage9dc).abs();check['share_abs_diff']=(check.S30_corrected_share_runtime-check.S30_corrected_share_stage9dc).abs();check.to_csv(evidence/'stage-9e-s30-reproduction.csv',index=False)
 out.to_csv(S30_DIR/'2026-player-predictions.csv',index=False,float_format='%.17g')
